create role anon;create role authenticated;
create schema auth;create schema game_private;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create table auth.users(id uuid primary key);
create table public.guilds(id uuid primary key);
create table public.guild_members(guild_id uuid,user_id uuid,player_key text,joined_at timestamptz default now(),primary key(guild_id,user_id));
create table public.quest_templates(id uuid primary key,guild_id uuid,key text,title text,category text,owner_type text,assigned_user_id uuid,active boolean default true,hidden_encounter boolean default false,visibility text default 'guild',xp_personal int default 100,xp_campaign int default 20,recurrence jsonb default '{"type":"repeatable"}');
create table public.quest_completions(id uuid primary key,guild_id uuid,quest_id uuid,completed_by uuid,effective_date date default current_date,completed_at timestamptz default now(),reversed_at timestamptz,occurrence_key text,campaign_xp_awarded int default 20,modifiers jsonb default '[]');
create table public.quest_completion_rewards(completion_id uuid,user_id uuid,personal_xp_awarded int,metadata jsonb default '{}',primary key(completion_id,user_id));
create table public.player_progress_public(guild_id uuid,user_id uuid,personal_xp int,level int,rank_key text,updated_at timestamptz,primary key(guild_id,user_id));
create table public.player_specializations(guild_id uuid,user_id uuid,specialization_key text,rank int);
create table public.campaigns(id uuid primary key,guild_id uuid,status text default 'active',started_at timestamptz default now(),campaign_xp int default 0,goal_xp int default 25000,completed_at timestamptz,chapter_key text);
create table public.campaign_contributions(campaign_id uuid,user_id uuid,campaign_xp int,primary key(campaign_id,user_id));
create table public.activity_events(id uuid primary key,guild_id uuid,actor_user_id uuid,event_type text,personal_xp int,campaign_xp int,metadata jsonb);
create function public.is_guild_member(g uuid) returns boolean language sql stable as $$select exists(select 1 from public.guild_members where guild_id=g and user_id=auth.uid())$$;
create function public.qb_effective_date(g uuid) returns date language sql stable as $$select current_date$$;
create function public.qb_level_for_xp(x int) returns int language sql immutable as $$select 1+floor(sqrt(greatest(0,x)/150.0))::int$$;
create function public.qb_rank_for_level(x int) returns text language sql immutable as $$select 'test-rank'::text$$;
alter table public.quest_templates add assignee_key text;
create function public.can_view_quest(q uuid) returns boolean language sql stable as $$select public.is_guild_member(guild_id) from public.quest_templates where id=q$$;
create function game_private.quest_cycle(q public.quest_templates,u uuid,d date) returns jsonb language sql as $$select '{"available":true}'::jsonb$$;
create function public.complete_quest_rested(uuid,text,text) returns jsonb language sql as $$select '{}'::jsonb$$;
